 function pathPoly(points,fill,stroke=null,lw=1){ctx.beginPath();points.forEach((p,i)=>{const [x,y]=p;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke()}}
 function line(a,b,color,width=1){ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}
 function isoCube(x,z,w,d,h,top,sideA,sideB,edge){let p0=project(x-w/2,z-d/2),p1=project(x+w/2,z-d/2),p2=project(x+w/2,z+d/2),p3=project(x-w/2,z+d/2);let t0=project(x-w/2,z-d/2,h),t1=project(x+w/2,z-d/2,h),t2=project(x+w/2,z+d/2,h),t3=project(x-w/2,z+d/2,h);pathPoly([p1,p2,t2,t1],sideA,edge);pathPoly([p2,p3,t3,t2],sideB,edge);pathPoly([t0,t1,t2,t3],top,edge);return {p0,p1,p2,p3,t0,t1,t2,t3}}
 function initWorld(){decor=[];for(let i=0;i<34;i++){let side=i%4,t=rand(-15,15),x,z;if(side===0){x=t;z=-15.7}else if(side===1){x=15.7;z=t}else if(side===2){x=t;z=15.7}else{x=-15.7;z=t}if(Math.abs(x)<4&&Math.abs(z)<4)continue;decor.push({x,z,w:rand(1.1,2.4),d:rand(1,2.2),h:rand(1.8,5.8),hue:Math.random()<.5?'cyan':'pink'})}for(let i=0;i<6;i++)decor.push({x:rand(-12,12),z:rand(-12,12),w:rand(.8,1.3),d:rand(.8,1.3),h:rand(1.4,2.2),hue:'pink',pillar:true});spawnPickups();enemies=[];for(let i=0;i<5;i++){let a=rand(0,Math.PI*2),r=rand(7,13);enemies.push({x:Math.cos(a)*r,z:Math.sin(a)*r,homeX:Math.cos(a)*r,homeZ:Math.sin(a)*r,hp:1,phase:rand(0,7),stun:0,attack:rand(1,3),dead:false})}}
