 function reset(){score=0;shards=0;timeLeft=75;health=100;energy=100;elapsed=0;gameOver=false;paused=false;slow=false;player.x=0;player.z=0;player.y=0;player.vx=player.vz=player.vy=0;player.dash=player.dashCd=player.invuln=0;initWorld();hud.style.display='block';overlay.classList.add('hidden');playing=true;last=performance.now()}
 function startOrRestart(){reset()}
 startBtn.addEventListener('click',startOrRestart);
